xml.Script:
        clBody    := 'AAAAAA';
        clTone    := '777777';
        clDisplay := '770000';
        clLegs    := '444444';

        R := 1;

        // segments
        CharW := R * 0.1;
        CharH := R * 0.15;
        SegW := R * 0.025; // Width 0f single segment
        SegS := R * 0.007; // Space between segments

        // dots
        ColonR := R * 0.025;

        // body
        Border := R * 0.05;
        Spacing := R * 0.025; // Space between digits
        CHeight := Border + Spacing + CharH;
        CLength := Border + CharW * 4 + ColonR + Spacing * 3;
        DDepth  := Border / 3;

        // Legs
        LegR := R * 0.025;
        LegH := R * 0.05;

        // Buttons
        ButtonH := R * 0.01;
        ButtonW := R * 0.05;

        D1 := ColonR + Spacing + CharW;
        D2 := D1 + CharW * 2 + Spacing;

        // digits from time
        Ht := 0; Mt := 0; St := 0; MSt := 0;
        DecodeTime(Time, Ht, Mt, St, MSt);
        N1 := Ht div 10;
        N2 := Ht mod 10;
        N3 := Mt div 10;
        N4 := Mt mod 10;

        if N1 = 0 then // remove leading zero
          N1 := -1;

        // visible segments
        Dig[-1] := 0000000;
        Dig[ 0] := 1111101;
        Dig[ 1] := 0110000;
        Dig[ 2] := 1010111;
        Dig[ 3] := 0110111;
        Dig[ 4] := 0111010;
        Dig[ 5] := 0101111;
        Dig[ 6] := 1101111;
        Dig[ 7] := 0110001;
        Dig[ 8] := 1111111;
        Dig[ 9] := 0111111;

