        // Upper buttons

        
            IE0 := 0;
            IE1 := 0;
            IE2 := 0;
            IE3 := 0;
            IE4 := 0;
            IE5 := 0;

            cl := clTone;

            CX3 := CLength / 2 - Border;
            CX4 := CLength / 2;
            Y1 :=-ButtonW;
            Y2 := ButtonW;
            Z1 := CHeight;
            Z2 := CHeight + ButtonH;
        

        
        
        

        // two dots

        
            DZ := CHeight / 2 + ColonR / 2 - Border;
        

        
            
        
        
            
        

        // legs

        
            LX := CLength - LegR * 2;
            LY := CHeight - LegR * 2;
        

        
            
                
            
        
        
        
        
        

        // segments

         // vertical
            SZ := (CharH - SegW) / 2;
            X1 := SegW;
            Y2 := SZ - SegS;
            Y1 := Y2 - SegW;

            Vx[0] :=-X1; Vz[0] :=-Y1;
            Vx[1] :=-X1; Vz[1] := Y1;
            Vx[2] :=  0; Vz[2] := Y2;
            Vx[3] := X1; Vz[3] := Y1;
            Vx[4] := X1; Vz[4] :=-Y1;
            Vx[5] :=  0; Vz[5] :=-Y2;
        

        
            
            
                
                

                
                    
                    
                    
                    
                    
                    
                    
                    
                
            
            
        

         // horizontal
            SX := CharW - SegW;
            Y1 := SegW;
            X2 := SX - SegS;
            X1 := X2 - SegW;

            Hx[0] :=-X1; Hz[0] :=-Y1;
            Hx[1] :=-X2; Hz[1] :=  0;
            Hx[2] :=-X1; Hz[2] := Y1;
            Hx[3] := X1; Hz[3] := Y1;
            Hx[4] := X2; Hz[4] :=  0;
            Hx[5] := X1; Hz[5] :=-Y1;
        

        
            
            
                
                

                
                    
                    
                    
                    
                    
                    
                    
                    
                
            
            
        

        
            
                Digs := Dig[Digit];

                A := Digs div 1000000 mod 10;
                B := Digs div 100000 mod 10;
                C := Digs div 10000 mod 10;
                D := Digs div 1000 mod 10;
                E := Digs div 100 mod 10;
                F := Digs div 10 mod 10;
                G := Digs div 1 mod 10;
